"""AI Engineering Example -- a minimal tool-calling dispatcher.

Shows *args/**kwargs and first-class functions used together to route a
parsed LLM tool-call request ({"name": ..., "arguments": {...}}) to the
matching Python function. This is the pattern behind every "function calling"
/ "tool use" feature in LLM APIs.

Run: python3 tool_dispatcher.py
"""
from __future__ import annotations
from collections.abc import Callable

ToolFn = Callable[..., str]

TOOLS: dict[str, ToolFn] = {}


def register_tool(name: str) -> Callable[[ToolFn], ToolFn]:
    """Tiny registration decorator -- functions are first-class, so we can
    store them in a plain dict keyed by the name the LLM will ask for."""

    def decorator(fn: ToolFn) -> ToolFn:
        TOOLS[name] = fn
        return fn

    return decorator


@register_tool("get_weather")
def get_weather(city: str, unit: str = "celsius") -> str:
    return f"Weather in {city}: 22 degrees {unit}"


@register_tool("search_docs")
def search_docs(query: str, *, top_k: int = 3) -> str:
    return f"Top {top_k} results for {query!r}"


def dispatch_tool_call(name: str, **kwargs: object) -> str:
    """Route a tool call by name, forwarding its arguments as **kwargs."""
    if name not in TOOLS:
        raise ValueError(f"Unknown tool: {name}")
    return TOOLS[name](**kwargs)


if __name__ == "__main__":
    # This is roughly what an LLM's tool-call response looks like once parsed.
    llm_tool_call = {
        "name": "search_docs",
        "arguments": {"query": "asyncio timeouts", "top_k": 2},
    }
    result = dispatch_tool_call(llm_tool_call["name"], **llm_tool_call["arguments"])
    print(result)  # Top 2 results for 'asyncio timeouts'

    print(dispatch_tool_call("get_weather", city="Bengaluru"))
    # Weather in Bengaluru: 22 degrees celsius

"""Decorators that take their own arguments need an extra level of nesting:
a function (`retry(times=3)`) that returns the actual decorator.

Run: python3 decorator_with_arguments.py
"""
from __future__ import annotations
import functools
from collections.abc import Callable
from typing import TypeVar

R = TypeVar("R")


def retry(times: int) -> Callable[[Callable[..., R]], Callable[..., R]]:
    def decorator(fn: Callable[..., R]) -> Callable[..., R]:
        @functools.wraps(fn)
        def wrapper(*args: object, **kwargs: object) -> R:
            last_error: Exception | None = None
            for attempt in range(1, times + 1):
                try:
                    return fn(*args, **kwargs)
                except Exception as e:  # deliberately broad for this demo
                    last_error = e
                    print(f"attempt {attempt} failed: {e}")
            assert last_error is not None
            raise last_error

        return wrapper

    return decorator


_calls = {"count": 0}


@retry(times=3)
def flaky_call() -> str:
    _calls["count"] += 1
    if _calls["count"] < 3:
        raise RuntimeError("simulated transient failure")
    return "success"


if __name__ == "__main__":
    print(flaky_call())
    # attempt 1 failed: simulated transient failure
    # attempt 2 failed: simulated transient failure
    # success

"""Why functools.wraps matters: without it, a decorated function loses its
own identity (__name__, __doc__, etc.), which breaks introspection,
debugging output, and tools that rely on it (docs generators, some
frameworks' route/registration logic).

Run: python3 functools_wraps.py
"""
from __future__ import annotations
import functools
from collections.abc import Callable
from typing import TypeVar

R = TypeVar("R")


def without_wraps(fn: Callable[..., R]) -> Callable[..., R]:
    def wrapper(*args: object, **kwargs: object) -> R:
        return fn(*args, **kwargs)

    return wrapper


def with_wraps(fn: Callable[..., R]) -> Callable[..., R]:
    @functools.wraps(fn)
    def wrapper(*args: object, **kwargs: object) -> R:
        return fn(*args, **kwargs)

    return wrapper


@without_wraps
def greet_a(name: str) -> str:
    """Return a greeting."""
    return f"Hello, {name}!"


@with_wraps
def greet_b(name: str) -> str:
    """Return a greeting."""
    return f"Hello, {name}!"


if __name__ == "__main__":
    print(greet_a.__name__)  # wrapper             <- WRONG, identity lost
    print(greet_a.__doc__)  # None                 <- WRONG, docstring lost

    print(greet_b.__name__)  # greet_b             <- correct
    print(greet_b.__doc__)  # Return a greeting.   <- correct

"""AI Engineering Example -- stacking retry + logging + timing decorators
around an LLM call, and observing the order they execute in.

Decorators apply bottom-up but EXECUTE outer-to-inner:

    @timed
    @logged
    @retry(times=2)
    def call_llm(): ...

is equivalent to `call_llm = timed(logged(retry(times=2)(call_llm)))`, so at
call time: timed starts -> logged starts -> retry runs (and may loop) ->
logged ends -> timed ends.

Run: python3 stacked_decorators.py
"""
from __future__ import annotations
import functools
import time
from collections.abc import Callable
from typing import TypeVar

R = TypeVar("R")


def timed(fn: Callable[..., R]) -> Callable[..., R]:
    @functools.wraps(fn)
    def wrapper(*args: object, **kwargs: object) -> R:
        start = time.perf_counter()
        result = fn(*args, **kwargs)
        print(f"[timed] {fn.__name__} took {time.perf_counter() - start:.3f}s")
        return result

    return wrapper


def logged(fn: Callable[..., R]) -> Callable[..., R]:
    @functools.wraps(fn)
    def wrapper(*args: object, **kwargs: object) -> R:
        print(f"[logged] calling {fn.__name__}")
        result = fn(*args, **kwargs)
        print(f"[logged] {fn.__name__} returned {result!r}")
        return result

    return wrapper


def retry(times: int) -> Callable[[Callable[..., R]], Callable[..., R]]:
    def decorator(fn: Callable[..., R]) -> Callable[..., R]:
        @functools.wraps(fn)
        def wrapper(*args: object, **kwargs: object) -> R:
            for attempt in range(1, times + 1):
                try:
                    return fn(*args, **kwargs)
                except Exception as e:  # deliberately broad for this demo
                    print(f"[retry] attempt {attempt} failed: {e}")
            raise RuntimeError("all retries exhausted")

        return wrapper

    return decorator


_state = {"attempts": 0}


@timed
@logged
@retry(times=2)
def call_llm(prompt: str) -> str:
    _state["attempts"] += 1
    if _state["attempts"] < 2:
        raise RuntimeError("simulated rate limit")
    return f"response to: {prompt}"


if __name__ == "__main__":
    print(call_llm("hello"))

"""Basic type hints: variables, function signatures, and built-in generic
containers. Python does NOT enforce these at runtime -- they're checked by
a separate tool (mypy, pyright) and read by editors/IDEs.

Run: python3 basic_type_hints.py
"""
from __future__ import annotations


def summarize(text: str, max_words: int = 50) -> str:
    words = text.split()
    return " ".join(words[:max_words])


def word_counts(texts: list[str]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for text in texts:
        for word in text.split():
            counts[word] = counts.get(word, 0) + 1
    return counts


def find_user(user_id: int, users: dict[int, str]) -> str | None:
    """`X | None` (not `Optional[X]`) is the modern way to say "this can be
    None" -- Python 3.10+ syntax, no `typing.Optional` import needed."""
    return users.get(user_id)


if __name__ == "__main__":
    print(summarize("advanced python for ai engineers is a learning repo", max_words=4))
    print(word_counts(["a b a", "b c"]))
    print(find_user(1, {1: "alice"}))
    print(find_user(99, {1: "alice"}))

"""A quick preview of `Protocol` (structural typing): any object with the
right methods/attributes satisfies the type, with no inheritance required.
Full depth -- generic protocols, runtime-checkable protocols -- lives in
11-protocols-generics.

Run: python3 protocol_preview.py
"""
from __future__ import annotations
from typing import Protocol


class TextModel(Protocol):
    def generate(self, prompt: str) -> str: ...


class LocalEchoModel:
    """Never mentions TextModel anywhere -- it satisfies the protocol just
    by having a matching `generate` method (structural typing, aka
    "duck typing with a type checker watching")."""

    def generate(self, prompt: str) -> str:
        return f"echo: {prompt}"


def run_prompt(model: TextModel, prompt: str) -> str:
    return model.generate(prompt)


if __name__ == "__main__":
    print(run_prompt(LocalEchoModel(), "hello"))  # echo: hello

"""AI Engineering Example -- a typed tool-calling contract combining
TypedDict, Literal, Callable, and Annotated so an agent, a tool registry,
and a type checker all agree on the exact shape of a tool call and its
result.

Run: python3 typed_tool_interface.py
"""
from __future__ import annotations
from collections.abc import Callable
from typing import Annotated, Literal, TypedDict

ToolStatus = Literal["ok", "error"]


class ToolCall(TypedDict):
    name: str
    arguments: dict[str, object]


class ToolResult(TypedDict):
    status: ToolStatus
    output: str


# Annotated attaches extra metadata to a type without changing what the type
# actually is -- a type checker still sees `int`; the metadata is there for
# documentation, or for tools (like Pydantic, see 09) that read it at runtime.
TopK = Annotated[int, "must be between 1 and 20"]

ToolFn = Callable[..., ToolResult]


def search_docs(query: str, top_k: TopK = 3) -> ToolResult:
    return {"status": "ok", "output": f"top {top_k} results for {query!r}"}


TOOLS: dict[str, ToolFn] = {"search_docs": search_docs}


def dispatch(call: ToolCall) -> ToolResult:
    tool = TOOLS.get(call["name"])
    if tool is None:
        return {"status": "error", "output": f"unknown tool: {call['name']}"}
    return tool(**call["arguments"])


if __name__ == "__main__":
    call: ToolCall = {"name": "search_docs", "arguments": {"query": "type hints", "top_k": 2}}
    print(dispatch(call))

    bad_call: ToolCall = {"name": "does_not_exist", "arguments": {}}
    print(dispatch(bad_call))

"""The same class, written twice, to make the boilerplate `@dataclass`
eliminates concrete instead of abstract.

Run: python3 dataclass_vs_plain_class.py
"""
from __future__ import annotations
from dataclasses import dataclass


class PlainPoint:
    def __init__(self, x: float, y: float) -> None:
        self.x = x
        self.y = y

    def __repr__(self) -> str:
        return f"PlainPoint(x={self.x!r}, y={self.y!r})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, PlainPoint):
            return NotImplemented
        return (self.x, self.y) == (other.x, other.y)


@dataclass
class DataclassPoint:
    x: float
    y: float


if __name__ == "__main__":
    a, b = PlainPoint(1, 2), PlainPoint(1, 2)
    c, d = DataclassPoint(1, 2), DataclassPoint(1, 2)

    print(a, a == b)  # PlainPoint(x=1, y=2) True
    print(c, c == d)  # DataclassPoint(x=1, y=2) True
    # Same behavior -- the dataclass version needed zero lines of __init__,
    # __repr__, or __eq__ code.

"""Field constraints (ge/le/min_length/...) and custom @field_validator
functions for rules a bare type hint can't express.

Requires: pydantic (see requirements.txt)
Run: python3 validators_and_constraints.py
"""
from __future__ import annotations
from pydantic import BaseModel, Field, ValidationError, field_validator


class SearchRequest(BaseModel):
    query: str = Field(min_length=1, max_length=500)
    top_k: int = Field(default=5, ge=1, le=20)

    @field_validator("query")
    @classmethod
    def query_must_not_be_blank(cls, value: str) -> str:
        if not value.strip():
            raise ValueError("query must not be blank")
        return value.strip()


if __name__ == "__main__":
    print(SearchRequest(query="  async generators  ", top_k=3))
    # query='async generators' top_k=3  <- whitespace stripped by the validator

    for bad_input in [
        {"query": "ok", "top_k": 100},  # violates le=20
        {"query": "   "},  # violates the custom validator
    ]:
        try:
            SearchRequest(**bad_input)
        except ValidationError as e:
            print(f"rejected {bad_input}: {e.errors()[0]['msg']}")

"""AI Engineering Example -- callable Tool objects with their own internal
state (call counts, config), instead of plain functions. __call__ is what
makes `tool(**arguments)` work exactly like calling a function while still
letting the tool carry state and other methods.

Run: python3 callable_tool_registry.py
"""
from __future__ import annotations


class Tool:
    def __init__(self, name: str) -> None:
        self.name = name
        self.call_count = 0

    def run(self, **kwargs: object) -> str:
        raise NotImplementedError

    def __call__(self, **kwargs: object) -> str:
        self.call_count += 1
        return self.run(**kwargs)

    def __repr__(self) -> str:
        return f"<Tool {self.name} calls={self.call_count}>"


class SearchTool(Tool):
    def __init__(self) -> None:
        super().__init__(name="search_docs")

    def run(self, *, query: str, top_k: int = 3) -> str:
        return f"top {top_k} results for {query!r}"


if __name__ == "__main__":
    search = SearchTool()

    print(search(query="advanced oop", top_k=2))  # calling the instance directly
    print(search(query="descriptors"))
    print(search)  # <Tool search_docs calls=2>  -- __repr__ shows tracked state

"""Descriptors: an object with __get__/__set__ controls attribute access on
ANOTHER class. This is the mechanism underneath @property, and a way to
write reusable validated-attribute logic without a full Pydantic model.

Run: python3 descriptors.py
"""
from __future__ import annotations


class PositiveNumber:
    """A reusable descriptor: any attribute using this class enforces
    "must be > 0" without repeating the check in every property."""

    def __set_name__(self, owner: type, name: str) -> None:
        self._name = f"_{name}"

    def __get__(self, instance: object, owner: type) -> float:
        return getattr(instance, self._name)

    def __set__(self, instance: object, value: float) -> None:
        if value <= 0:
            raise ValueError(f"expected a positive number, got {value}")
        setattr(instance, self._name, value)


class RateLimiter:
    max_calls_per_minute = PositiveNumber()  # descriptor instance, shared logic

    def __init__(self, max_calls_per_minute: float) -> None:
        self.max_calls_per_minute = max_calls_per_minute  # goes through __set__


if __name__ == "__main__":
    limiter = RateLimiter(max_calls_per_minute=60)
    print(limiter.max_calls_per_minute)  # 60 -- goes through __get__

    try:
        limiter.max_calls_per_minute = -5
    except ValueError as e:
        print(f"caught: {e}")

"""Operator overloading: implementing __add__/__eq__/__repr__ lets custom
objects work with +, ==, and print() naturally. Use sparingly -- only when
the operator's meaning is obvious and unsurprising (see When NOT To Use).

Run: python3 operator_overloading.py
"""
from __future__ import annotations


class Vector:
    def __init__(self, x: float, y: float) -> None:
        self.x = x
        self.y = y

    def __add__(self, other: "Vector") -> "Vector":
        return Vector(self.x + other.x, self.y + other.y)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Vector):
            return NotImplemented
        return self.x == other.x and self.y == other.y

    def __repr__(self) -> str:
        return f"Vector({self.x}, {self.y})"


if __name__ == "__main__":
    a = Vector(1, 2)
    b = Vector(3, 4)

    print(a + b)  # Vector(4, 6)  -- calls a.__add__(b)
    print(a + b == Vector(4, 6))  # True

"""A bounded type parameter restricts what T can be -- here, anything with
an `id: str` attribute -- so the generic class can rely on `.id` existing
without knowing the concrete type in advance.

Requires: Python 3.12+
Run: python3.12 bounded_typevar.py
"""
from __future__ import annotations
from dataclasses import dataclass
from typing import Protocol


class HasId(Protocol):
    id: str


class Repository[T: HasId]:
    """T is bounded to HasId -- a type checker allows `.id` access below
    for ANY T, because every valid T is guaranteed to have it."""

    def __init__(self) -> None:
        self._items: dict[str, T] = {}

    def add(self, item: T) -> None:
        self._items[item.id] = item  # only valid because T is bounded by HasId

    def get(self, item_id: str) -> T | None:
        return self._items.get(item_id)


@dataclass
class Document:
    id: str
    text: str


if __name__ == "__main__":
    repo: Repository[Document] = Repository()
    repo.add(Document(id="doc-1", text="Bounded TypeVars restrict generic params."))

    found = repo.get("doc-1")
    print(found)
    print(repo.get("missing"))  # None

"""Generic classes with modern PEP 695 syntax (Python 3.12+): `class
Stack[T]:` declares the type parameter directly in the class header --
no `typing.Generic`/`TypeVar` import needed.

Requires: Python 3.12+
Run: python3.12 generic_classes.py
"""
from __future__ import annotations


class Stack[T]:
    def __init__(self) -> None:
        self._items: list[T] = []

    def push(self, item: T) -> None:
        self._items.append(item)

    def pop(self) -> T:
        return self._items.pop()

    def __len__(self) -> int:
        return len(self._items)


if __name__ == "__main__":
    numbers: Stack[int] = Stack()
    numbers.push(1)
    numbers.push(2)
    print(numbers.pop())  # 2
    print(len(numbers))  # 1

    names: Stack[str] = Stack()
    names.push("alice")
    print(names.pop())  # alice
    # A type checker would reject `names.push(5)` -- `names` is `Stack[str]`

"""AI Engineering Example -- a model-provider abstraction built entirely
from structural typing: any object with a matching `generate` method works,
so swapping providers (or writing a fake for tests) never requires a shared
base class, registration, or inheritance.

Requires: Python 3.12+
Run: python3.12 model_provider_abstraction.py
"""
from __future__ import annotations
from typing import Protocol


class ModelProvider(Protocol):
    def generate(self, prompt: str) -> str: ...


class OpenAIStyleProvider:
    def __init__(self, model: str) -> None:
        self.model = model

    def generate(self, prompt: str) -> str:
        return f"[{self.model}] {prompt[::-1]}"  # pretend completion


class LocalEchoProvider:
    def generate(self, prompt: str) -> str:
        return f"echo: {prompt}"


class FakeTestProvider:
    """Satisfies ModelProvider with zero setup -- ideal for unit tests."""

    def generate(self, prompt: str) -> str:
        return "fixed test response"


def run_pipeline(provider: ModelProvider, prompt: str) -> str:
    """This function has NO idea which concrete provider it received --
    and doesn't need to. Swapping providers means passing a different
    object in, nothing else changes."""
    return provider.generate(prompt)


if __name__ == "__main__":
    for provider in [OpenAIStyleProvider("gpt-mini"), LocalEchoProvider(), FakeTestProvider()]:
        print(run_pipeline(provider, "hello"))

"""Structural typing with Protocol: unrelated classes satisfy the same
type just by having the right methods -- no shared base class needed.
@runtime_checkable additionally lets isinstance() check a Protocol
directly (checking method presence only, not signatures).

Run: python3 structural_typing.py
"""
from __future__ import annotations
from typing import Protocol, runtime_checkable


@runtime_checkable
class Embedder(Protocol):
    def embed(self, text: str) -> list[float]: ...


class LocalHashEmbedder:
    """Never imports or inherits from Embedder -- it satisfies the
    protocol purely by shape."""

    def embed(self, text: str) -> list[float]:
        return [float(len(text) % 10)]


class RemoteApiEmbedder:
    def embed(self, text: str) -> list[float]:
        return [0.1, 0.2, 0.3]  # pretend API call


def embed_all(embedder: Embedder, texts: list[str]) -> list[list[float]]:
    return [embedder.embed(t) for t in texts]


if __name__ == "__main__":
    print(embed_all(LocalHashEmbedder(), ["hi", "hello"]))
    print(embed_all(RemoteApiEmbedder(), ["hi"]))

    print(isinstance(LocalHashEmbedder(), Embedder))  # True -- structural check
    print(isinstance("not an embedder", Embedder))  # False

"""The raw Server-Sent Events wire format -- no framework needed to
understand it. Each event is plain text: a `data:` line (or several),
followed by a BLANK line to mark the event's end. This is exactly what a
browser's EventSource (or any SSE client) parses.

Run: python3 sse_format_basics.py
"""
from __future__ import annotations
from collections.abc import Iterator


def format_sse_event(data: str, *, event: str | None = None) -> str:
    lines = []
    if event is not None:
        lines.append(f"event: {event}")
    lines.append(f"data: {data}")
    return "\n".join(lines) + "\n\n"  # the blank line is what terminates an event


def parse_sse_stream(raw: str) -> Iterator[str]:
    """A minimal client-side parser: split on the blank-line event
    terminator and pull out each event's data payload."""
    for chunk in raw.split("\n\n"):
        if not chunk.strip():
            continue
        for line in chunk.splitlines():
            if line.startswith("data: "):
                yield line.removeprefix("data: ")


if __name__ == "__main__":
    stream = (
        format_sse_event("Hello") + format_sse_event("World") + format_sse_event("done", event="end")
    )
    print(repr(stream))

    for data in parse_sse_stream(stream):
        print("event data:", data)

"""A minimal circuit breaker: after too many consecutive failures, stop
even TRYING the call for a cooldown period (the "open" state) instead of
retrying a service that's clearly down -- protecting both the caller (fast
failure instead of repeated timeouts) and the struggling downstream service.

Run: python3 circuit_breaker.py
"""
from __future__ import annotations
import time
from enum import Enum, auto


class CircuitState(Enum):
    CLOSED = auto()  # normal operation -- calls go through
    OPEN = auto()  # too many recent failures -- calls are rejected immediately
    HALF_OPEN = auto()  # cooldown elapsed -- let ONE call through to test recovery


class CircuitOpenError(Exception):
    pass


class CircuitBreaker:
    def __init__(self, *, failure_threshold: int, cooldown_seconds: float) -> None:
        self.failure_threshold = failure_threshold
        self.cooldown_seconds = cooldown_seconds
        self.state = CircuitState.CLOSED
        self.failure_count = 0
        self.opened_at: float | None = None

    def _maybe_recover(self) -> None:
        if (
            self.state is CircuitState.OPEN
            and self.opened_at is not None
            and time.monotonic() - self.opened_at >= self.cooldown_seconds
        ):
            self.state = CircuitState.HALF_OPEN

    def call(self, fn) -> object:
        self._maybe_recover()

        if self.state is CircuitState.OPEN:
            raise CircuitOpenError("circuit is open -- failing fast without calling")

        try:
            result = fn()
        except Exception:
            self.failure_count += 1
            if self.failure_count >= self.failure_threshold:
                self.state = CircuitState.OPEN
                self.opened_at = time.monotonic()
            raise
        else:
            self.failure_count = 0
            self.state = CircuitState.CLOSED
            return result


if __name__ == "__main__":
    breaker = CircuitBreaker(failure_threshold=3, cooldown_seconds=0.2)

    def always_fails() -> None:
        raise RuntimeError("downstream is down")

    for i in range(3):
        try:
            breaker.call(always_fails)
        except RuntimeError:
            print(f"call {i + 1}: failed normally, state={breaker.state.name}")

    try:
        breaker.call(always_fails)
    except CircuitOpenError:
        print(f"call 4: rejected immediately, state={breaker.state.name}")

    time.sleep(0.25)  # let the cooldown elapse

    def now_succeeds() -> str:
        return "recovered"

    print("after cooldown:", breaker.call(now_succeeds), f"state={breaker.state.name}")

"""A custom exception hierarchy lets callers catch broadly (any APIError)
or narrowly (just RateLimitError), and lets retry logic ask "is this
retryable?" by checking a TYPE rather than parsing an error message.

Run: python3 exception_hierarchy.py
"""
from __future__ import annotations


class APIError(Exception):
    """Base for every error this client can raise."""


class RetryableAPIError(APIError):
    """Transient -- retrying with backoff is reasonable."""


class RateLimitError(RetryableAPIError):
    pass


class ServerOverloadedError(RetryableAPIError):
    pass


class NonRetryableAPIError(APIError):
    """Retrying will never help -- the request itself is wrong."""


class AuthenticationError(NonRetryableAPIError):
    pass


class InvalidRequestError(NonRetryableAPIError):
    pass


def classify(exc: APIError) -> str:
    if isinstance(exc, RetryableAPIError):
        return "retryable"
    return "not retryable"


if __name__ == "__main__":
    for exc in [RateLimitError("429"), AuthenticationError("401"), ServerOverloadedError("503")]:
        print(f"{type(exc).__name__}: {classify(exc)}")

    # Catching the BASE class catches every subclass beneath it.
    try:
        raise RateLimitError("too many requests")
    except APIError as e:
        print(f"caught via base class: {type(e).__name__}")

"""AI Engineering Example -- retrying an LLM call correctly: classify the
failure (retryable vs not) using an exception hierarchy, back off with
jitter between retries, and fail fast on anything that retrying can't fix.

Run: python3 llm_retry_with_backoff.py
"""
from __future__ import annotations
import asyncio
import random


class LLMAPIError(Exception):
    pass


class RateLimitError(LLMAPIError):
    """Retryable -- the provider is asking us to slow down."""


class InvalidPromptError(LLMAPIError):
    """NOT retryable -- the request itself is malformed; retrying sends
    the exact same broken request again."""


def backoff_delay(attempt: int, *, base: float = 0.05, cap: float = 2.0) -> float:
    exponential = min(cap, base * (2 ** (attempt - 1)))
    return exponential + random.uniform(0, exponential * 0.5)


_attempts = {"count": 0}


async def call_llm(prompt: str) -> str:
    if prompt == "":
        raise InvalidPromptError("prompt must not be empty")
    _attempts["count"] += 1
    if _attempts["count"] < 3:
        raise RateLimitError("429: rate limited, try again shortly")
    return f"response to: {prompt}"


async def call_llm_with_retry(prompt: str, *, max_attempts: int = 5) -> str:
    for attempt in range(1, max_attempts + 1):
        try:
            return await call_llm(prompt)
        except RateLimitError as e:
            if attempt == max_attempts:
                raise
            delay = backoff_delay(attempt)
            print(f"attempt {attempt}: {e} -- backing off {delay:.2f}s")
            await asyncio.sleep(delay)
        except InvalidPromptError as e:
            print(f"attempt {attempt}: {e} -- not retrying, failing fast")
            raise
    raise AssertionError("unreachable")


async def main() -> None:
    print(await call_llm_with_retry("summarize this document"))

    try:
        await call_llm_with_retry("")
    except InvalidPromptError:
        print("gave up immediately on the invalid prompt, as expected")


if __name__ == "__main__":
    asyncio.run(main())

"""Deciding whether to retry: check the exception TYPE, not just "did it
fail?" -- retrying a non-retryable error just wastes time and delays the
real, unfixable failure from surfacing.

Run: python3 retry_vs_fail_fast.py
"""
from __future__ import annotations


class RetryableAPIError(Exception):
    pass


class NonRetryableAPIError(Exception):
    pass


def call_api(mode: str) -> str:
    if mode == "rate_limited":
        raise RetryableAPIError("429 Too Many Requests")
    if mode == "bad_auth":
        raise NonRetryableAPIError("401 Unauthorized")
    return "ok"


def call_with_retry(mode: str, *, max_attempts: int = 3) -> str:
    for attempt in range(1, max_attempts + 1):
        try:
            return call_api(mode)
        except RetryableAPIError as e:
            print(f"attempt {attempt}: retryable failure ({e}) -- retrying")
            if attempt == max_attempts:
                raise
        except NonRetryableAPIError as e:
            print(f"non-retryable failure ({e}) -- failing fast, no retry")
            raise


if __name__ == "__main__":
    try:
        call_with_retry("bad_auth")
    except NonRetryableAPIError:
        print("gave up immediately, as expected\n")

    try:
        call_with_retry("rate_limited", max_attempts=2)
    except RetryableAPIError:
        print("exhausted all retries")

"""Memoization is caching applied SPECIFICALLY to function results keyed
by arguments -- every memoization is a cache, but not every cache is
memoization (an LLM response cache keyed by a custom string, or an HTTP
cache keyed by URL, are caches without being "memoized function calls").

`functools.cache` also requires every argument to be HASHABLE -- this is
the most common wall people hit trying to memoize something.

Run: python3 cache_vs_memoization.py
"""
from __future__ import annotations
from functools import cache


@cache
def word_count(text: str) -> int:
    """Memoization: caching THIS function's output, keyed by its args."""
    return len(text.split())


def cache_lookup(store: dict[str, str], key: str) -> str | None:
    """Caching WITHOUT memoization -- a plain dict acting as a cache, not
    tied to memoizing any particular function call."""
    return store.get(key)


if __name__ == "__main__":
    print(word_count("advanced python for ai engineers"))  # 5
    print(word_count("advanced python for ai engineers"))  # cache hit

    store = {"prompt:hello": "cached response for hello"}
    print(cache_lookup(store, "prompt:hello"))

    # functools.cache requires hashable arguments -- a list breaks it.
    try:
        word_count(["not", "hashable"])  # type: ignore[arg-type]
    except TypeError as e:
        print(f"caught: {e}")

"""Common JSON serialization pitfalls: datetimes, Enums, and bytes don't
serialize by default -- each needs an explicit conversion or a custom
`default=` function.

Run: python3 serialization_pitfalls.py
"""
from __future__ import annotations
import json
from datetime import datetime
from enum import Enum


class Role(str, Enum):
    """Inheriting from `str` makes Enum members ALSO plain strings, which
    is why this specific pattern serializes fine below -- a plain
    `class Role(Enum)` would NOT."""

    USER = "user"
    ASSISTANT = "assistant"


def json_default(value: object) -> str:
    """A `default=` function json.dumps calls for anything it doesn't
    already know how to serialize."""
    if isinstance(value, datetime):
        return value.isoformat()
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    raise TypeError(f"Object of type {type(value).__name__} is not JSON serializable")


if __name__ == "__main__":
    # Pitfall 1: datetime isn't JSON-serializable by default.
    try:
        json.dumps({"created_at": datetime(2024, 1, 1)})
    except TypeError as e:
        print(f"pitfall 1 caught: {e}")
    print("fixed:", json.dumps({"created_at": datetime(2024, 1, 1)}, default=json_default))

    # Pitfall 2: a plain Enum does NOT serialize, even though it "looks" like a string.
    class PlainRole(Enum):
        USER = "user"

    try:
        json.dumps({"role": PlainRole.USER})
    except TypeError as e:
        print(f"pitfall 2 caught: {e}")

    # ...but a `str, Enum` mixin DOES, because it genuinely IS a str at runtime.
    print("str-Enum works directly:", json.dumps({"role": Role.USER}))

    # Pitfall 3: bytes aren't JSON-serializable either.
    try:
        json.dumps({"payload": b"raw bytes"})
    except TypeError as e:
        print(f"pitfall 3 caught: {e}")
    print("fixed:", json.dumps({"payload": b"raw bytes"}, default=json_default))

