"""Liveness vs readiness -- two different questions an orchestrator (e.g.
Kubernetes) asks a service. Liveness: "is the process stuck/deadlocked and
needs a restart?" Readiness: "can it currently handle traffic?" Conflating
them causes either unnecessary restarts or traffic sent to a broken pod.

Run: python3 health_checks.py
"""
from __future__ import annotations
from dataclasses import dataclass, field

from fastapi import FastAPI
from fastapi.testclient import TestClient


@dataclass
class ServiceState:
    llm_client_ready: bool = False
    vector_db_ready: bool = False
    startup_errors: list[str] = field(default_factory=list)

    @property
    def is_ready(self) -> bool:
        return self.llm_client_ready and self.vector_db_ready and not self.startup_errors


state = ServiceState()
app = FastAPI()


@app.get("/health/live")
def liveness() -> dict[str, str]:
    """Answers ONLY "is the process running and responsive?" -- always
    returns ok if this handler can even execute. Never checks dependencies:
    a slow downstream API should not get this pod restarted."""
    return {"status": "ok"}


@app.get("/health/ready")
def readiness() -> dict[str, object]:
    """Answers "should traffic be routed here right now?" -- checks
    dependencies that must be up for a request to actually succeed."""
    if not state.is_ready:
        return {"status": "not_ready", "errors": state.startup_errors}
    return {"status": "ready"}


if __name__ == "__main__":
    client = TestClient(app)
    print(client.get("/health/live").json())
    print(client.get("/health/ready").json())  # not_ready -- dependencies not initialized yet

    state.llm_client_ready = True
    state.vector_db_ready = True
    print(client.get("/health/ready").json())  # ready

"""Service layering -- separate "what the API looks like" (route) from
"what the business logic does" (service) from "how data is fetched/stored"
(repository). Each layer only knows about the one below it, so any layer
can be tested or swapped independently.

Run: python3 service_layering.py
"""
from __future__ import annotations
from dataclasses import dataclass
from typing import Protocol


@dataclass
class Document:
    id: str
    text: str


class DocumentRepository(Protocol):
    """The service layer only depends on THIS shape -- not on any
    particular database or vector store."""

    def get(self, doc_id: str) -> Document | None: ...


class InMemoryDocumentRepository:
    """One concrete implementation -- a real one might wrap Postgres or a
    vector DB, with no changes needed above this layer."""

    def __init__(self) -> None:
        self._docs = {"doc-1": Document(id="doc-1", text="Contextvars isolate async state.")}

    def get(self, doc_id: str) -> Document | None:
        return self._docs.get(doc_id)


class DocumentService:
    """Business logic lives here -- no HTTP concepts, no SQL. Depends only
    on the repository Protocol, so it's trivial to unit test with a fake."""

    def __init__(self, repository: DocumentRepository) -> None:
        self._repository = repository

    def summarize(self, doc_id: str) -> str:
        doc = self._repository.get(doc_id)
        if doc is None:
            raise ValueError(f"no document with id={doc_id!r}")
        return doc.text[:20] + ("..." if len(doc.text) > 20 else "")


def handle_summarize_request(doc_id: str, service: DocumentService) -> dict[str, str]:
    """Stands in for a route handler -- translates HTTP-shaped input into a
    service call and the result back into a response body."""
    try:
        summary = service.summarize(doc_id)
    except ValueError as exc:
        return {"error": str(exc)}
    return {"doc_id": doc_id, "summary": summary}


if __name__ == "__main__":
    service = DocumentService(InMemoryDocumentRepository())
    print(handle_summarize_request("doc-1", service))
    print(handle_summarize_request("doc-missing", service))

"""Tool-calling interface -- a typed registry mapping a tool NAME (what an
LLM emits) to a validated input model and a callable. This is the pattern
underneath every "function calling" / "tool use" API: the model never
calls Python directly, it emits a name + arguments that your code
validates and dispatches.

Run: python3 tool_calling_interface.py
"""
from __future__ import annotations
from typing import Any, Callable
from pydantic import BaseModel


class SearchDocsArgs(BaseModel):
    query: str
    top_k: int = 3


class SendEmailArgs(BaseModel):
    to: str
    subject: str


def search_docs(args: SearchDocsArgs) -> str:
    return f"found {args.top_k} result(s) for {args.query!r}"


def send_email(args: SendEmailArgs) -> str:
    return f"email sent to {args.to} with subject {args.subject!r}"


class ToolRegistry:
    """Maps a tool name to (its input schema, the function to call)."""

    def __init__(self) -> None:
        self._tools: dict[str, tuple[type[BaseModel], Callable[[Any], str]]] = {}

    def register(self, name: str, schema: type[BaseModel], fn: Callable[[Any], str]) -> None:
        self._tools[name] = (schema, fn)

    def dispatch(self, name: str, raw_args: dict[str, object]) -> str:
        """Simulates handling one tool call the model asked for: look up
        the tool, VALIDATE the model's raw arguments against its schema
        (never trust them blindly), then call the function."""
        if name not in self._tools:
            raise ValueError(f"unknown tool: {name!r}")
        schema, fn = self._tools[name]
        validated_args = schema.model_validate(raw_args)
        return fn(validated_args)


if __name__ == "__main__":
    registry = ToolRegistry()
    registry.register("search_docs", SearchDocsArgs, search_docs)
    registry.register("send_email", SendEmailArgs, send_email)

    # What an LLM's tool-call response typically looks like: a name + a raw dict.
    print(registry.dispatch("search_docs", {"query": "contextvars", "top_k": 2}))
    print(registry.dispatch("send_email", {"to": "a@example.com", "subject": "hi"}))

    try:
        registry.dispatch("search_docs", {"query": "x", "top_k": "not-a-number"})
    except Exception as exc:
        print(f"rejected bad tool call: {type(exc).__name__}")

